package com.nextrade.service; import com.nextrade.common.identifier.*; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.time.*; import java.util.*; import javax.crypto.SecretKey;
public final class JwtTokenService implements com.nextrade.service.ports.RefreshTokenFactory {private final JwtKeyRing ring;private final Duration ttl;public JwtTokenService(JwtKeyRing ring,Duration ttl){this.ring=ring;this.ttl=ttl;}public String issue(UserId userId,SessionId sessionId){Instant now=Instant.now();return Jwts.builder().id(sessionId.asString()).subject(userId.asString()).claim("token_type","refresh").header().keyId(ring.activeKid()).and().issuedAt(Date.from(now)).expiration(Date.from(now.plus(ttl))).signWith(ring.active()).compact();}public TokenClaims parse(String token){Jws<Claims> jws=Jwts.parser().verifyWith(resolveKey(token)).build().parseSignedClaims(token);Claims c=jws.getPayload();if(!"refresh".equals(c.get("token_type",String.class)))throw new JwtException("Wrong token type");return new TokenClaims(UserId.parse(c.getSubject()),SessionId.parse(c.getId()),c.getExpiration().toInstant());}private SecretKey resolveKey(String token){String kid=JwtKidResolver.resolve(token);return ring.key(kid);}}
